def get_bounding_box (grid ,target_color ):
    """
    Finds the bounding box coordinates of a specific color in a 2D grid.
    Returns the subgrid defined by the bounding box.
    """
    rows =len (grid )
    cols =len (grid [0 ])

    min_r ,max_r =rows ,-1 
    min_c ,max_c =cols ,-1 
    found =False 

    for r in range (rows ):
        for c in range (cols ):
            if grid [r ][c ]==target_color :
                found =True 
                if r <min_r :min_r =r 
                if r >max_r :max_r =r 
                if c <min_c :min_c =c 
                if c >max_c :max_c =c 

    if not found :
        return []

    return [row [min_c :max_c +1 ]for row in grid [min_r :max_r +1 ]]

